mapper.select:
SELECT p.*, c.category_name as categoryName
FROM product p
LEFT JOIN product_category c ON p.category_id = c.id


        AND p.product_name LIKE CONCAT('%', #{productName}, '%')


        AND (p.category_id = #{categoryId} OR p.category_id IN (SELECT id FROM product_category WHERE parent_id = #{categoryId}))


        AND p.is_international = #{isInternational}


        AND p.original_price >= #{minOriginalPrice}


        AND p.original_price <= #{maxOriginalPrice}


ORDER BY p.create_time DESC
